public function getTownLevel() : int
{
   if(this.townProsperity == 0)
   {
      return 0;
   }
   if(this.townProsperity < 500)
   {
      return 1;
   }
   if(this.townProsperity < 1000)
   {
      return 2;
   }
   if(this.townProsperity < 2000)
   {
      return 3;
   }
   if(this.townProsperity < 4000)
   {
      return 4;
   }
   return 5;
}
